U = "functions"
fn("absolute-difference", "Absolute Difference", U, "easy", "Parameters and return values", "Write `diff(a, b)` returning how far apart two numbers are, always as a non-negative value.", "def diff(a, b):\n    return abs(a - b)", [((3, 8), 5), ((8, 3), 5)], [(0, 0), (-2, 2)])
fn("clamp-a-value", "Clamp a Value", U, "easy", "Parameters and return values", "Write `clamp(x, low, high)` returning `x`, but no lower than `low` and no higher than `high`.", "def clamp(x, low, high):\n    return max(low, min(x, high))", [((5, 0, 10), 5), ((-3, 0, 10), 0)], [(11, 0, 10), (0, 0, 0)])
fn("first-and-last-pair", "First and Last Item", U, "easy", "Parameters and return values", "Write `ends(items)` returning a pair of the first and last items of a list with at least one item.", "def ends(items):\n    return (items[0], items[-1])", [([1, 2, 3], (1, 3)), ([7], (7, 7))], [(["a", "b"], )])
fn("greeting-with-default", "Greeting With a Default", U, "easy", "Default and keyword arguments", "Write `hello(name, greeting=\"Hello\")` returning text like `\"Hello, Ada!\"`. If no greeting is given, use the default.", 'def hello(name, greeting="Hello"):\n    return f"{greeting}, {name}!"', [("Ada", "Hello, Ada!"), (("Lin", "Hi"), "Hi, Lin!")], [("", ), ("Sam", "Hey")])
fn("sum-any-number-of-values", "Sum Any Number of Values", U, "medium", "Default and keyword arguments", "Write `total(*values)` that accepts any number of arguments and returns their sum. With no arguments it returns 0.", "def total(*values):\n    result = 0\n    for value in values:\n        result += value\n    return result", [((1, 2, 3), 6), ((), 0)], [(5, ), (1, -1, 1, -1)])
exprs("apply-twice", "Apply a Function Twice", U, "medium", "Functions as values", "Write `twice(f, x)` that calls the function `f` on `x`, then on that result, and returns the final value. A function is a value in Python, so it can be passed in like any other.", "def twice(f, x):\n    return f(f(x))", [("twice(abs, -3)", 3), ("twice(str, 5)", "5")], ['twice(int, "7")', "twice(abs, 0)"])
exprs("transform-every-item", "Transform Every Item", U, "medium", "Functions as values", "Write `apply_all(f, items)` returning a new list with `f` applied to each item.", "def apply_all(f, items):\n    return [f(item) for item in items]", [("apply_all(abs, [-1, 2])", [1, 2]), ("apply_all(str, [1, 2])", ["1", "2"])], ["apply_all(abs, [])", 'apply_all(len, ["a", "bb"])'])
exprs("keep-if-true", "Keep Items That Pass", U, "medium", "Functions as values", "Write `keep(f, items)` returning the items for which `f(item)` is truthy, in order, without using `filter`.", "def keep(f, items):\n    return [item for item in items if f(item)]", [("keep(bool, [0, 1, 2])", [1, 2]), ('keep(len, ["", "a"])', ["a"])], ["keep(abs, [0, 0])", "keep(bool, [])"])
fn("largest-by-length", "Longest Item", U, "easy", "Functions as values", "Write `longest(words)` returning the longest word, using `max` with `key=len`. The first wins a tie. An empty list gives None.", "def longest(words):\n    if not words:\n        return None\n    return max(words, key=len)", [(["a", "abc", "ab"], "abc"), ([], None)], [(["xx", "yy"], ), (["one"], )])
fn("is-sorted-helper", "Is It Sorted", U, "easy", "Breaking problems into helpers", "Write `is_sorted(items)` returning True if each item is no larger than the next. Empty and single-item lists count as sorted.", "def is_sorted(items):\n    for i in range(len(items) - 1):\n        if items[i] > items[i + 1]:\n            return False\n    return True", [([1, 2, 2, 3], True), ([3, 1], False)], [([], ), ([5], ), ([1, 2, 0], )])
fn("count-primes-with-helper", "Primes in a Range", U, "medium", "Breaking problems into helpers", "Write `primes_between(a, b)` returning a list of primes from `a` to `b` inclusive. A helper function that tests one number keeps this tidy.", "def is_prime(n):\n    if n < 2:\n        return False\n    i = 2\n    while i * i <= n:\n        if n % i == 0:\n            return False\n        i += 1\n    return True\n\ndef primes_between(a, b):\n    return [n for n in range(a, b + 1) if is_prime(n)]", [((1, 10), [2, 3, 5, 7]), ((14, 16), [])], [(2, 2), (20, 30), (0, 1)])
fn("rounded-average-helper", "Rounded Class Average", U, "medium", "Breaking problems into helpers", "Write `class_average(scores)` returning the mean rounded to one decimal place, or 0.0 for an empty list.", "def class_average(scores):\n    if not scores:\n        return 0.0\n    return round(sum(scores) / len(scores), 1)", [([70, 80, 90], 80.0), ([], 0.0)], [([1, 2], ), ([33, 34], ), ([100], )])
exprs("compose-two-functions", "Compose Two Functions", U, "hard", "Functions as values", "Write `compose(f, g)` that returns a new function. Calling the new function with `x` gives `f(g(x))`. An inner function can use `f` and `g` from the outer one.", "def compose(f, g):\n    def combined(x):\n        return f(g(x))\n    return combined", [('compose(abs, int)("-5")', 5), ("compose(str, abs)(-2)", "2")], ["compose(len, str)(12345)", "compose(int, str)(7)"])

