fn("first-three-letters", "First Three Letters", U, "easy", "Indexing and slicing", "Write `first_three(text)` returning the first three characters, or all of it if shorter.", "def first_three(text):\n    return text[:3]", [("python", "pyt"), ("hi", "hi")], [("", ), ("abc", )])
fn("reverse-a-string", "Reverse a String", U, "easy", "Indexing and slicing", "Write `reverse(text)` returning the characters in reverse order. A slice with a step of -1 does this.", "def reverse(text):\n    return text[::-1]", [("abc", "cba"), ("", "")], [("a", ), ("racecar", ), ("ab cd", )])
fn("middle-character", "Middle Character", U, "easy", "Indexing and slicing", "Write `middle_char(text)` for a non-empty string. Return the middle character for odd lengths, and the middle two for even lengths.", "def middle_char(text):\n    mid = len(text) // 2\n    if len(text) % 2:\n        return text[mid]\n    return text[mid - 1:mid + 1]", [("abc", "b"), ("abcd", "bc")], [("a", ), ("ab", ), ("abcde", )])
fn("swap-first-and-last-letter", "Swap First and Last Letter", U, "easy", "Indexing and slicing", "Write `swap_ends(text)`. Strings cannot be changed in place, so build a new one. Strings shorter than 2 stay the same.", "def swap_ends(text):\n    if len(text) < 2:\n        return text\n    return text[-1] + text[1:-1] + text[0]", [("code", "eodc"), ("a", "a")], [("", ), ("ab", ), ("hello", )])
fn("count-vowels", "Count Vowels", U, "easy", "Counting characters", "Write `count_vowels(text)` counting a, e, i, o, u in either case.", 'def count_vowels(text):\n    return sum(1 for ch in text.lower() if ch in "aeiou")', [("Hello", 2), ("xyz", 0)], [("", ), ("AEIOU", ), ("Programming", )])
fn("count-a-character", "Count One Character", U, "easy", "Counting characters", "Write `count_char(text, ch)` counting how many times `ch` appears, without using `.count`.", "def count_char(text, ch):\n    total = 0\n    for letter in text:\n        if letter == ch:\n            total += 1\n    return total", [(("banana", "a"), 3), (("hi", "z"), 0)], [("", "a"), ("aaa", "a"), ("AaA", "a")])
fn("most-common-letter", "Most Common Letter", U, "medium", "Counting characters", "Write `most_common(text)` returning the character that appears most often in a non-empty string. If there is a tie, return the one that appears first.", "def most_common(text):\n    counts = {}\n    for ch in text:\n        counts[ch] = counts.get(ch, 0) + 1\n    best = text[0]\n    for ch in text:\n        if counts[ch] > counts[best]:\n            best = ch\n    return best", [("banana", "a"), ("abab", "a")], [("z", ), ("aabbb", ), ("xyz", )])
fn("count-words", "Count Words", U, "easy", "String methods", "Write `word_count(text)`. Words are separated by any spaces, so ignore extra ones. `.split()` handles this.", "def word_count(text):\n    return len(text.split())", [("hello big world", 3), ("   ", 0)], [("", ), ("one", ), ("  two   words ", )])
fn("capitalise-each-word", "Capitalise Each Word", U, "easy", "String methods", "Write `title_words(text)` making the first letter of each word uppercase and the rest lowercase, with one space between words.", 'def title_words(text):\n    return " ".join(word.capitalize() for word in text.split())', [("hello WORLD", "Hello World"), ("", "")], [("a b", ), ("  many   spaces ", ), ("pYTHON", )])
fn("replace-spaces", "Replace Spaces", U, "easy", "String methods", "Write `slug(text)` returning lowercase text with each space replaced by a hyphen.", 'def slug(text):\n    return text.lower().replace(" ", "-")', [("Hello World", "hello-world"), ("OK", "ok")], [("", ), ("a b c", )])
fn("starts-and-ends-with", "Starts and Ends the Same", U, "easy", "String methods", "Write `same_ends(text, part)` returning True if `text` both starts and ends with `part`.", "def same_ends(text, part):\n    return text.startswith(part) and text.endswith(part)", [(("abcab", "ab"), True), (("abc", "a"), False)], [("", "a"), ("aa", "a"), ("xyx", "x")])
fn("only-digits-sum", "Sum the Digits in Text", U, "easy", "Counting characters", "Write `sum_digits_in(text)` adding up every digit character in the text and ignoring the rest.", "def sum_digits_in(text):\n    return sum(int(ch) for ch in text if ch.isdigit())", [("a1b2c3", 6), ("none", 0)], [("", ), ("99", ), ("1 2", )])
fn("remove-vowels", "Remove Vowels", U, "easy", "Building strings", "Write `no_vowels(text)` returning the text with a, e, i, o, u removed, in either case.", 'def no_vowels(text):\n    return "".join(ch for ch in text if ch.lower() not in "aeiou")', [("Education", "dctn"), ("xyz", "xyz")], [("", ), ("AEIOU", ), ("Hello World", )])
fn("repeat-each-character", "Repeat Each Character", U, "easy", "Building strings", "Write `stretch(text, n)` repeating each character `n` times. `stretch(\"ab\", 2)` gives `\"aabb\"`.", 'def stretch(text, n):\n    return "".join(ch * n for ch in text)', [(("ab", 2), "aabb"), (("x", 3), "xxx")], [("", 5), ("ab", 0), ("hi", 1)])
fn("run-length-encoding", "Run-Length Encoding", U, "medium", "Building strings", "Write `encode(text)` replacing each run of a repeated character with the character and its count, so `\"aaabb\"` becomes `\"a3b2\"`.", 'def encode(text):\n    if not text:\n        return ""\n    out = []\n    current, count = text[0], 1\n    for ch in text[1:]:\n        if ch == current:\n            count += 1\n        else:\n            out.append(f"{current}{count}")\n            current, count = ch, 1\n    out.append(f"{current}{count}")\n    return "".join(out)', [("aaabb", "a3b2"), ("", "")], [("a", ), ("abc", ), ("zzzzzz", ), ("aabbaa", )])
fn("caesar-shift", "Caesar Shift", U, "medium", "Building strings", "Write `shift(text, k)` moving each lowercase letter forward `k` places, wrapping from z to a. Leave anything else unchanged. `ord` and `chr` convert between letters and numbers.", 'def shift(text, k):\n    out = []\n    for ch in text:\n        if "a" <= ch <= "z":\n            out.append(chr((ord(ch) - 97 + k) % 26 + 97))\n        else:\n            out.append(ch)\n    return "".join(out)', [(("abc", 1), "bcd"), (("xyz", 3), "abc")], [("hello world", 13), ("", 5), ("a!", 26), ("b", -1)])
fn("is-string-palindrome", "Palindrome Word", U, "easy", "Palindromes and comparison", "Write `is_palindrome(text)` returning True if the text reads the same both ways, ignoring case.", "def is_palindrome(text):\n    lowered = text.lower()\n    return lowered == lowered[::-1]", [("Level", True), ("abc", False)], [("", ), ("a", ), ("Noon", ), ("ab", )])
fn("palindrome-letters-only", "Palindrome Sentence", U, "medium", "Palindromes and comparison", "Write `is_clean_palindrome(text)` ignoring case and anything that is not a letter or digit.", "def is_clean_palindrome(text):\n    kept = [ch.lower() for ch in text if ch.isalnum()]\n    return kept == kept[::-1]", [("A man, a plan, a canal: Panama", True), ("race a car", False)], [("", ), (" ", ), ("0P", ), ("No lemon, no melon", )])
fn("are-anagrams", "Are They Anagrams", U, "easy", "Palindromes and comparison", "Write `anagrams(a, b)` returning True if both use exactly the same letters the same number of times, ignoring case.", "def anagrams(a, b):\n    return sorted(a.lower()) == sorted(b.lower())", [(("Listen", "Silent"), True), (("abc", "abd"), False)], [("", ""), ("a", "aa"), ("Dormitory", "dirtyroom")])
fn("longest-word-in-sentence", "Longest Word in a Sentence", U, "easy", "String methods", "Write `longest_word(text)` returning the longest word. The first wins a tie, and empty text gives an empty string.", 'def longest_word(text):\n    best = ""\n    for word in text.split():\n        if len(word) > len(best):\n            best = word\n    return best', [("the quick brown", "quick"), ("", "")], [("a bb cc", ), ("one", )])
fn("common-prefix-of-two", "Common Prefix of Two Words", U, "medium", "Palindromes and comparison", "Write `common_prefix(a, b)` returning the longest start they share.", 'def common_prefix(a, b):\n    out = ""\n    for x, y in zip(a, b):\n        if x != y:\n            break\n        out += x\n    return out', [(("flower", "flow"), "flow"), (("dog", "car"), "")], [("", "x"), ("same", "same"), ("ab", "abc")])
fn("is-subsequence-of-text", "Letters in Order", U, "medium", "Palindromes and comparison", "Write `in_order(short, long)` returning True if all letters of `short` appear in `long` in the same order, not necessarily next to each other.", "def in_order(short, long):\n    i = 0\n    for ch in long:\n        if i < len(short) and short[i] == ch:\n            i += 1\n    return i == len(short)", [(("ace", "abcde"), True), (("aec", "abcde"), False)], [("", "x"), ("x", ""), ("aa", "a"), ("abc", "abc")])
fn("compress-spaces", "Tidy the Spaces", U, "easy", "String methods", "Write `tidy(text)` removing spaces at both ends, and reducing every run of spaces inside to one.", 'def tidy(text):\n    return " ".join(text.split())', [("  a   b ", "a b"), ("ok", "ok")], [("", ), ("     ", ), ("x  y  z", )])
fn("alternate-case-builder", "Alternating Case", U, "medium", "Building strings", "Write `alternate(text)` making characters at even positions uppercase and those at odd positions lowercase.", 'def alternate(text):\n    return "".join(ch.upper() if i % 2 == 0 else ch.lower() for i, ch in enumerate(text))', [("hello", "HeLlO"), ("", "")], [("A", ), ("ABC", ), ("a b", )])

