fn("rotate-list-right", "Rotate a List", U, "medium", "List basics", "Write `rotate(items, k)` returning a new list moved right by `k` places, with items wrapping around.", "def rotate(items, k):\n    if not items:\n        return []\n    k %= len(items)\n    return items[-k:] + items[:-k] if k else items[:]", [(([1, 2, 3, 4], 1), [4, 1, 2, 3]), (([], 3), [])], [([1, 2], 2), ([1, 2, 3], 4), ([1], 5)])
