fn("transpose-a-matrix", "Transpose a Matrix", U, "medium", "Nested lists and matrices", "Write `transpose(matrix)` swapping rows and columns of a rectangular matrix.", "def transpose(matrix):\n    if not matrix:\n        return []\n    return [[row[c] for row in matrix] for c in range(len(matrix[0]))]", [([[1, 2, 3], [4, 5, 6]], [[1, 4], [2, 5], [3, 6]]), ([], [])], [([[1]], ), ([[1], [2]], )])
fn("diagonal-sum", "Diagonal Sum", U, "easy", "Nested lists and matrices", "Write `diagonal(matrix)` adding the items on the main diagonal of a square matrix.", "def diagonal(matrix):\n    return sum(matrix[i][i] for i in range(len(matrix)))", [([[1, 2], [3, 4]], 5), ([], 0)], [([[9]], ), ([[1, 0, 0], [0, 2, 0], [0, 0, 3]], )])
fn("spiral-matrix-order", "Spiral Order", U, "hard", "Nested lists and matrices", "Write `spiral(matrix)` listing a rectangular matrix's items going clockwise from the top-left corner, moving inwards.", "def spiral(matrix):\n    out = []\n    grid = [row[:] for row in matrix]\n    while grid:\n        out.extend(grid.pop(0))\n        if grid and grid[0]:\n            for row in grid:\n                out.append(row.pop())\n        if grid:\n            out.extend(grid.pop()[::-1])\n        if grid and grid[0]:\n            for row in grid[::-1]:\n                out.append(row.pop(0))\n    return out", [([[1, 2, 3], [4, 5, 6], [7, 8, 9]], [1, 2, 3, 6, 9, 8, 7, 4, 5]), ([], [])], [([[1]], ), ([[1, 2]], ), ([[1], [2]], ), ([[1, 2], [3, 4], [5, 6]], )])
