fn("get-with-a-default", "Look Up With a Default", U, "easy", "Dictionary basics", "Write `lookup(prices, item)` returning the item's price, or 0 if it is not there, using `.get`.", "def lookup(prices, item):\n    return prices.get(item, 0)", [(({"tea": 3}, "tea"), 3), (({"tea": 3}, "milk"), 0)], [({}, "x"), ({"a": 0}, "a")])
fn("total-prices", "Add Up a Cart", U, "easy", "Dictionary basics", "Write `cart_total(prices, cart)`. `prices` maps items to prices, and `cart` is a list of items. Add up what the cart costs, counting unknown items as 0.", "def cart_total(prices, cart):\n    return sum(prices.get(item, 0) for item in cart)", [(({"tea": 3, "jam": 5}, ["tea", "jam", "tea"]), 11), (({}, ["x"]), 0)], [({"a": 1}, []), ({"a": 2}, ["b", "a"])])
fn("key-with-largest-value", "Key With the Largest Value", U, "medium", "Dictionary basics", "Write `top_key(scores)` returning the key with the largest value, or None for an empty dictionary. On a tie, return the alphabetically first key.", "def top_key(scores):\n    if not scores:\n        return None\n    return min(scores, key=lambda k: (-scores[k], k))", [({"a": 1, "b": 3}, "b"), ({}, None)], [({"z": 2, "m": 2}, ), ({"only": 0}, )])
fn("group-by-first-letter", "Group by First Letter", U, "medium", "Grouping and counting", "Write `by_letter(words)` returning a dictionary from each first letter to the list of words starting with it, in their original order.", "def by_letter(words):\n    groups = {}\n    for word in words:\n        groups.setdefault(word[0], []).append(word)\n    return groups", [(["ant", "bee", "ape"], {"a": ["ant", "ape"], "b": ["bee"]}), ([], {})], [(["x"], ), (["bb", "ba", "c"], )])
fn("word-frequency", "Word Frequency", U, "medium", "Grouping and counting", "Write `frequencies(text)` counting how often each lowercase word appears. Words are separated by spaces, and uppercase counts as lowercase.", "def frequencies(text):\n    counts = {}\n    for word in text.lower().split():\n        counts[word] = counts.get(word, 0) + 1\n    return counts", [("the cat the", {"the": 2, "cat": 1}), ("", {})], [("A a A", ), ("one", )])
fn("group-scores-by-pass", "Pass or Fail Groups", U, "medium", "Grouping and counting", "Write `split_scores(scores, mark)` returning a dictionary with keys `\"pass\"` and `\"fail\"`. Scores at or above `mark` pass, and each list keeps the original order.", 'def split_scores(scores, mark):\n    result = {"pass": [], "fail": []}\n    for score in scores:\n        result["pass" if score >= mark else "fail"].append(score)\n    return result', [(([40, 60], 50), {"pass": [60], "fail": [40]}), (([], 1), {"pass": [], "fail": []})], [([50], 50), ([1, 2, 3], 10)])
